def max_officers_eliminated(T, test_cases):
    results = []
    for case in test_cases:
        N, C, P = case
        P.sort()
        max_eliminated = 0
        for i in range(N):
            if abs(C - P[i]) > 1:
                max_eliminated += 1
                C -= 1
            else:
                break
        if C < min(P):
            results.append((max_eliminated, 1))
        else:
            results.append((max_eliminated, -1))
    return results

# Read input
T = int(input())
test_cases = []
for _ in range(T):
    N = int(input())
    C = int(input())
    P = list(map(int, input().split()))
    test_cases.append((N, C, P))

# Get results
results = max_officers_eliminated(T, test_cases)

# Print results
for result in results:
    print(result[0], result[1])
